import type { IndependentObjectIndex } from "./independent-source-objects.js";
import type { CanoVerifiedRoster } from "./cano-chol-in-nucleus-roster.js";
export type SourceIdentityLevel = "specimen" | "section" | "cell" | "component" | "synapse";
export type SourceRelationType = "same_physical_object" | "same_section" | "same_source_population" | "co_display_only";
export type SourceIdentityNode = { status: "known" | "unknown" | "ambiguous" | "not_applicable"; id: string | null; locator: string | null; reason: string | null; key?: string | null };
export type SourceIdentityParts = { sourceId: string; releaseId: string; namespace: string; objectKind: string; objectId: string };
export type SourceParentEvidence = SourceIdentityParts & { parentLevel: SourceIdentityLevel; childLevel: SourceIdentityLevel; parentId: string; childId: string; locator: string };
export type SourceHierarchyInput = SourceIdentityParts & { objectLocator: string; objectLevel: SourceIdentityLevel | "population"; unit: string; nodes: Record<SourceIdentityLevel, SourceIdentityNode>; population: SourceIdentityNode; parentEvidence?: Partial<Record<SourceIdentityLevel, Omit<SourceParentEvidence, "objectKind" | "objectId">>> };
export type SourceIdentityHierarchy = SourceHierarchyInput & { documentType: "source_identity_hierarchy"; schemaVersion: "0.1.0"; key: string; parents: Record<SourceIdentityLevel, { key: string | null; status: string; reason?: string; locator?: string; parentId?: string; childId?: string }>; authority: "source_scoped_identity_metadata_only"; geometryTransferAllowed: false; registrationCount: 0 };
export type SourceRelationEvidence = { id: string; type: SourceRelationType; leftKey: string; rightKey: string; locator: string; bindings: { left: SourceIdentityParts & Record<string, string>; right: SourceIdentityParts & Record<string, string> }; qc: Record<string, boolean>; sourceReceipts: { path: string; bytes: number; algorithm: "SHA-256" | "MD5"; digest: string; status: "verified"; representation?: string }[]; boundary?: string };
export type SourceRelationship = { documentType: "source_object_relationship"; schemaVersion: "0.1.0"; type: SourceRelationType; leftKey: string; rightKey: string; evidence: SourceRelationEvidence | null; qc: { status: string }; reason: string; grantsGeometryTransfer: false; sameCellInternalAdmission: false; registrationCount: 0 };
export const SOURCE_RELATION_TYPES: readonly SourceRelationType[];
export const SOURCE_IDENTITY_LEVELS: readonly SourceIdentityLevel[];
export function sourceNamespacedObjectKey(identity: SourceIdentityParts | null): string | null;
export function createSourceIdentityHierarchy(input: SourceHierarchyInput): SourceIdentityHierarchy;
export function validateSourceIdentityHierarchy(hierarchy: SourceIdentityHierarchy): SourceIdentityHierarchy;
export function resolveSourceRelationship(left: SourceIdentityHierarchy, right: SourceIdentityHierarchy, requested?: SourceRelationType, evidence?: SourceRelationEvidence | null, verifiedSourceEvidence?: readonly SourceRelationEvidence[]): SourceRelationship;
export function independentSourceIdentityHierarchy(index: IndependentObjectIndex, key: string): SourceIdentityHierarchy;
export function canoSourceIdentityHierarchy(registry: unknown, roster: CanoVerifiedRoster, profileId: string, rowKey?: string | null): SourceIdentityHierarchy;
export function canoSourcePopulationEvidence(registry: unknown, roster: CanoVerifiedRoster, profileId: string, leftRowKey?: string | null, rightRowKey?: string | null): SourceRelationEvidence;
